#' Weighting and Doubly Robust Estimators
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param extra .
#' @param weights .
#' @param cluster .
#' @param estimand .
#' @param doRa .
#' @param doIpw .
#' @param doAipw .
#' @param doIpwra .
#' @param link .
#' @param trim .
#' @param trimLo .
#' @param trimHi .
#' @param level .
#' @param showPom .
#' @param showWeights .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pom} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$wdiag} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$effects$asDF}
#'
#' \code{as.data.frame(results$effects)}
#'
#' @export
wtest <- function(
    data,
    outcome,
    treat,
    covs,
    extra,
    weights,
    cluster,
    estimand = "all",
    doRa = TRUE,
    doIpw = TRUE,
    doAipw = TRUE,
    doIpwra = TRUE,
    link = "logit",
    trim = "none",
    trimLo = 0.05,
    trimHi = 0.95,
    level = 95,
    showPom = FALSE,
    showWeights = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("wtest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(extra)) extra <- jmvcore::resolveQuo(jmvcore::enquo(extra))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(extra), extra, NULL),
            `if`( ! missing(weights), weights, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- wtestOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        extra = extra,
        weights = weights,
        cluster = cluster,
        estimand = estimand,
        doRa = doRa,
        doIpw = doIpw,
        doAipw = doAipw,
        doIpwra = doIpwra,
        link = link,
        trim = trim,
        trimLo = trimLo,
        trimHi = trimHi,
        level = level,
        showPom = showPom,
        showWeights = showWeights,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- wtestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

